parameters {
    real a;
    real b[n_factors];
}
transformed parameters {
    real r_hat[n];
    for (i in 1:n) {
        r_hat[i] <- a;
        for (j in 1:n_factors)
            r_hat[i] <- r_hat[i] + b[j] * model_matrix[i,j];
